//! Interval literals and arithmetic read as in Spark 4.2.0: output name, type,
//! value and error class (`tests/fixtures/spark-4.2.0/interval-arithmetic.json`,
//! generated by `tests/scripts/gen_interval_goldens.py` from a real Spark run).
#![forbid(unsafe_code)]

use std::path::PathBuf;

use arrow_array::Array;
use arrow_array::cast::AsArray;
use futures::executor::block_on;
use krishiv_session::Session;
use serde_json::Value;

type R<T = ()> = Result<T, Box<dyn std::error::Error>>;

/// What the engine answers for one expression.
#[derive(Debug, Default, PartialEq, Eq)]
struct Answer {
    name: Option<String>,
    data_type: Option<String>,
    value: Option<String>,
    error_class: Option<String>,
}

fn answer(session: &Session, expr: &str) -> Answer {
    block_on(async {
        let df = match session.sql(&format!("SELECT {expr}")).await {
            Ok(df) => df,
            Err(e) => {
                return Answer {
                    error_class: Some(e.error_class().name().to_owned()),
                    ..Answer::default()
                };
            }
        };
        let schema = match df.schema().await {
            Ok(s) => s,
            Err(e) => {
                return Answer {
                    error_class: Some(e.error_class().name().to_owned()),
                    ..Answer::default()
                };
            }
        };
        let field = &schema.fields()[0];
        let mut a = Answer {
            name: Some(field.name().to_owned()),
            data_type: krishiv_types::DataType::from_arrow_field(field)
                .ok()
                .map(|t| t.simple_string()),
            ..Answer::default()
        };
        let text = df.select_expr([format!(
            "CAST(`{}` AS STRING)",
            field.name().replace('`', "``")
        )]);
        let batches = match text {
            Ok(df) => df.collect().await,
            Err(e) => Err(e),
        };
        match batches {
            Ok(batches) => {
                let column = batches[0].column(0);
                let strings = column.as_string_view();
                a.value = strings.is_valid(0).then(|| strings.value(0).to_owned());
            }
            Err(e) => a.error_class = Some(e.error_class().name().to_owned()),
        }
        a
    })
}

fn fixture() -> R<Value> {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/fixtures/spark-4.2.0/interval-arithmetic.json");
    Ok(serde_json::from_str(&std::fs::read_to_string(path)?)?)
}

/// Spark raises these without a class (design P2-T001b Q1); Krishiv's class is
/// `INTERVAL_ARITHMETIC_OVERFLOW.WITHOUT_SUGGESTION`.
const WITHOUT_SUGGESTION: &str = "INTERVAL_ARITHMETIC_OVERFLOW.WITHOUT_SUGGESTION";

#[test]
fn intervals_match_spark() -> R {
    let doc = fixture()?;
    let cases = doc["cases"].as_array().ok_or("no cases")?;
    assert!(cases.len() > 150, "{} cases", cases.len());
    let mut wrong = Vec::new();
    for case in cases {
        let expr = case["expr"].as_str().ok_or("no expr")?;
        let session = Session::new()?;
        let zone = case["zone"].as_str().ok_or("zone")?;
        block_on(session.sql(&format!("SET spark.sql.session.timeZone = {zone}")))?;
        let ansi = case["ansi"].as_bool().ok_or("ansi")?;
        block_on(session.sql(&format!("SET spark.sql.ansi.enabled = {ansi}")))?;
        let got = answer(&session, expr);
        let text = |k: &str| case[k].as_str().map(str::to_owned);
        let mut want = Answer {
            name: text("name"),
            data_type: text("type"),
            value: text("value"),
            error_class: text("error_class").or_else(|| text("value_error_class")),
        };
        if want.error_class.as_deref() == Some("UNCLASSIFIED") {
            want.error_class = Some(WITHOUT_SUGGESTION.to_owned());
        }
        if got != want {
            wrong.push(format!("{expr}\n   got {got:?}\n  want {want:?}"));
        }
    }
    assert!(
        wrong.is_empty(),
        "{} wrong:\n{}",
        wrong.len(),
        wrong.join("\n")
    );
    Ok(())
}

/// Spark answers these in an interval type. Until they run (P2-T001b unit 4)
/// they say so, rather than that an interval is not an interval.
#[test]
fn interval_arguments_not_built_yet_are_named_as_unsupported() -> R {
    let session = Session::new()?;
    for q in [
        "SELECT sum(i) FROM VALUES (interval '1' day) AS t(i)",
        "SELECT avg(i) FROM VALUES (interval '1' month) AS t(i)",
        "SELECT try_sum(i) FROM VALUES (interval '1' day) AS t(i)",
        "SELECT try_avg(i) FROM VALUES (interval '1' day) AS t(i)",
        "SELECT abs(interval '1' day)",
    ] {
        let e = block_on(session.sql(q)).err().ok_or(q)?;
        assert_eq!(e.error_class().name(), "KRISHIV_UNSUPPORTED_FEATURE", "{q}");
    }
    Ok(())
}

/// `sql`'s rows, each column cast to string, one line per row.
fn rows(session: &Session, sql: &str) -> R<Vec<String>> {
    block_on(async {
        let df = session.sql(sql).await?;
        let names: Vec<String> = df
            .schema()
            .await?
            .fields()
            .iter()
            .map(|f| format!("CAST(`{}` AS STRING)", f.name().replace('`', "``")))
            .collect();
        let mut out = Vec::new();
        for batch in df.select_expr(names)?.collect().await? {
            for row in 0..batch.num_rows() {
                let cells: Vec<String> = batch
                    .columns()
                    .iter()
                    .map(|c| {
                        let s = c.as_string_view();
                        if s.is_valid(row) {
                            s.value(row).to_owned()
                        } else {
                            "NULL".to_owned()
                        }
                    })
                    .collect();
                out.push(cells.join("|"));
            }
        }
        Ok(out)
    })
}

/// Columns, not literals: `try_*` goes row by row only past a failure, and
/// intervals sort, group and join as their values.
#[test]
fn interval_columns_behave_as_values() -> R {
    let session = Session::new()?;
    block_on(session.sql(
        "CREATE TEMPORARY VIEW m AS SELECT * FROM VALUES \
         (INTERVAL '2147483647' MONTH, 1), (INTERVAL '1' MONTH, 0), \
         (INTERVAL '-3' MONTH, 2), (CAST(NULL AS INTERVAL MONTH), 3) AS t(i, n)",
    ))?;
    assert_eq!(
        rows(
            &session,
            "SELECT try_add(i, INTERVAL '1' MONTH), try_divide(i, n) FROM m ORDER BY n"
        )?,
        [
            "INTERVAL '2' MONTH|NULL",
            "NULL|INTERVAL '178956970-7' YEAR TO MONTH",
            "INTERVAL '-2' MONTH|INTERVAL '-0-2' YEAR TO MONTH",
            "NULL|NULL",
        ]
    );
    let e = block_on(async {
        session
            .sql("SELECT i + INTERVAL '1' MONTH FROM m")
            .await?
            .collect()
            .await
    })
    .err()
    .ok_or("the overflow did not raise")?;
    assert_eq!(
        e.error_class().name(),
        "INTERVAL_ARITHMETIC_OVERFLOW.WITH_SUGGESTION"
    );
    assert_eq!(
        rows(&session, "SELECT i FROM m ORDER BY i NULLS LAST")?,
        [
            "INTERVAL '-3' MONTH",
            "INTERVAL '1' MONTH",
            "INTERVAL '2147483647' MONTH",
            "NULL",
        ]
    );
    block_on(session.sql(
        "CREATE TEMPORARY VIEW d AS SELECT * FROM VALUES \
         (INTERVAL '1' DAY), (INTERVAL '24' HOUR), (INTERVAL '2' DAY) AS t(i)",
    ))?;
    assert_eq!(
        rows(&session, "SELECT i, count(*) FROM d GROUP BY i ORDER BY i")?,
        [
            "INTERVAL '1 00' DAY TO HOUR|2",
            "INTERVAL '2 00' DAY TO HOUR|1"
        ]
    );
    assert_eq!(
        rows(&session, "SELECT count(*) FROM d a JOIN d b ON a.i = b.i")?,
        ["5"]
    );
    assert_eq!(
        rows(
            &session,
            "SELECT count(*) FROM d WHERE i IN (INTERVAL '48' HOUR)"
        )?,
        ["1"]
    );
    Ok(())
}

/// A session whose zone is not UTC: `TIMESTAMP_NTZ` and `TIMESTAMP` convert
/// through it, in both directions.
#[test]
fn a_cast_to_a_coarser_end_field_drops_what_is_below_it() -> R {
    let session = Session::new()?;
    assert_eq!(
        rows(
            &session,
            "SELECT DATE '2024-01-01' + CAST(INTERVAL '13' MONTH AS INTERVAL YEAR), \
             CAST(INTERVAL '-13' MONTH AS INTERVAL YEAR) = INTERVAL '-1' YEAR, \
             CAST(INTERVAL '1 02:03' DAY TO MINUTE AS INTERVAL DAY) = INTERVAL '1' DAY, \
             CAST(INTERVAL '-90' SECOND AS INTERVAL MINUTE) = INTERVAL '-1' MINUTE, \
             CAST(INTERVAL '1' YEAR AS INTERVAL MONTH) = INTERVAL '12' MONTH, \
             element_at(CAST(array(INTERVAL '13' MONTH) AS ARRAY<INTERVAL YEAR>), 1) \
             = INTERVAL '1' YEAR, \
             CAST(named_struct('a', INTERVAL '13' MONTH, 'b', INTERVAL '1.5' SECOND) \
             AS STRUCT<a: INTERVAL YEAR, b: INTERVAL SECOND>).b = INTERVAL '1.5' SECOND"
        )?,
        ["2025-01-01|true|true|true|true|true|true"]
    );
    block_on(session.sql(
        "CREATE TEMPORARY VIEW n AS SELECT * FROM VALUES \
         (INTERVAL '13' MONTH), (CAST(NULL AS INTERVAL MONTH)) AS t(i)",
    ))?;
    assert_eq!(
        rows(
            &session,
            "SELECT CAST(i AS INTERVAL YEAR) = INTERVAL '1' YEAR, \
             TRY_CAST(i AS INTERVAL YEAR) = INTERVAL '1' YEAR FROM n"
        )?,
        ["true|true", "NULL|NULL"]
    );
    Ok(())
}

#[test]
fn interval_function_names_read_in_any_case() -> R {
    let session = Session::new()?;
    for (expr, name, value) in [
        (
            "TRY_ADD(INTERVAL '1' DAY, INTERVAL '2' DAY)",
            "try_add(INTERVAL '1' DAY, INTERVAL '2' DAY)",
            "INTERVAL '3' DAY",
        ),
        (
            "Try_Divide(INTERVAL '4' MONTH, 2)",
            "try_divide(INTERVAL '4' MONTH, 2)",
            "INTERVAL '0-2' YEAR TO MONTH",
        ),
        (
            "TRY_SUBTRACT(DATE '2024-01-02', DATE '2024-01-01')",
            "try_subtract(DATE '2024-01-02', DATE '2024-01-01')",
            "INTERVAL '1' DAY",
        ),
        (
            "POSITIVE(INTERVAL '1' DAY)",
            "(+ INTERVAL '1' DAY)",
            "INTERVAL '1' DAY",
        ),
    ] {
        let got = answer(&session, expr);
        assert_eq!(got.error_class, None, "{expr}");
        assert_eq!(got.name.as_deref(), Some(name), "{expr}");
        assert_eq!(got.value.as_deref(), Some(value), "{expr}");
    }
    Ok(())
}

#[test]
fn a_try_function_evaluates_a_nondeterministic_operand_once_per_row() -> R {
    let session = Session::new()?;
    assert_eq!(
        rows(
            &session,
            "SELECT try_divide(INTERVAL '12' MONTH, monotonically_increasing_id()) FROM range(3)"
        )?,
        [
            "NULL",
            "INTERVAL '1-0' YEAR TO MONTH",
            "INTERVAL '0-6' YEAR TO MONTH",
        ]
    );
    assert_eq!(
        rows(
            &session,
            "SELECT try_divide(INTERVAL '1000' DAY, rand(42)) = INTERVAL '1000' DAY / rand(42) \
             FROM range(3)"
        )?,
        ["true", "true", "true"]
    );
    Ok(())
}

#[test]
fn an_operand_read_as_another_type_can_make_the_result_null() -> R {
    let session = Session::new()?;
    block_on(session.sql("SET spark.sql.ansi.enabled = false"))?;
    for expr in [
        "INTERVAL '1' DAY * s",
        "s + INTERVAL '1' DAY",
        "s - INTERVAL '1' DAY",
        "s - DATE '2024-01-01'",
    ] {
        assert_eq!(
            rows(
                &session,
                &format!("SELECT i IS NULL FROM (SELECT {expr} AS i FROM VALUES ('bad') t(s))")
            )?,
            ["true"],
            "{expr}"
        );
    }
    Ok(())
}

#[test]
fn a_mixed_timestamp_difference_reads_both_sides_without_a_zone() -> R {
    let session = Session::new()?;
    block_on(session.sql("SET spark.sql.session.timeZone = America/Los_Angeles"))?;
    // 02:30 doesn't exist in that zone on that day.
    assert_eq!(
        rows(
            &session,
            "SELECT date'2024-03-11' - timestamp_ntz'2024-03-10 02:30:00', \
             timestamp_ntz'2024-03-10 02:30:00' - timestamp'2024-03-10 00:00:00', \
             timestamp'2024-03-11 00:00:00' - timestamp_ntz'2024-03-10 02:30:00', \
             '2024-03-10 02:30:00' - timestamp_ntz'2024-03-11 00:00:00'"
        )?,
        [
            "INTERVAL '0 21:30:00' DAY TO SECOND|INTERVAL '0 02:30:00' DAY TO SECOND|\
             INTERVAL '0 21:30:00' DAY TO SECOND|INTERVAL '-0 21:30:00' DAY TO SECOND"
        ]
    );
    Ok(())
}

#[test]
fn an_interval_expression_over_no_rows_is_empty() -> R {
    let session = Session::new()?;
    for expr in [
        "transform(CAST(array() AS ARRAY<INT>), x -> INTERVAL '1' DAY * x)",
        "transform(CAST(array() AS ARRAY<INT>), x -> x * INTERVAL '1' MONTH)",
        "transform(CAST(array() AS ARRAY<INT>), x -> INTERVAL '1' DAY / x)",
        "transform(CAST(array() AS ARRAY<INTERVAL DAY>), x -> x * 2)",
        "transform(CAST(array() AS ARRAY<DATE>), x -> x + INTERVAL '1' MONTH)",
        "transform(CAST(array() AS ARRAY<TIMESTAMP>), x -> x + INTERVAL '1' DAY)",
        "transform(CAST(array() AS ARRAY<DATE>), x -> DATE '2024-01-01' - x)",
        "transform(CAST(array() AS ARRAY<TIMESTAMP>), x -> TIMESTAMP '2024-01-01' - x)",
        "transform(CAST(array() AS ARRAY<INTERVAL DAY>), x -> x + INTERVAL '1' DAY)",
        "transform(CAST(array() AS ARRAY<INTERVAL DAY>), x -> try_add(x, INTERVAL '1' DAY))",
    ] {
        assert_eq!(rows(&session, &format!("SELECT {expr}"))?, ["[]"], "{expr}");
    }
    Ok(())
}

#[test]
fn a_lambda_can_return_an_interval() -> R {
    let session = Session::new()?;
    assert_eq!(
        rows(
            &session,
            "SELECT transform(array(1, 2), x -> INTERVAL '1' MONTH * x), \
             transform(array(INTERVAL '1' DAY), x -> x + INTERVAL '1' DAY), \
             filter(array(INTERVAL '1' DAY, INTERVAL '-1' DAY), x -> x > INTERVAL '0' DAY)"
        )?,
        [
            "[INTERVAL '0-1' YEAR TO MONTH, INTERVAL '0-2' YEAR TO MONTH]|\
             [INTERVAL '2' DAY]|[INTERVAL '1' DAY]"
        ]
    );
    Ok(())
}

#[test]
fn a_nested_interval_cast_to_strings_renders_each_value() -> R {
    let session = Session::new()?;
    assert_eq!(
        rows(
            &session,
            "SELECT CAST(array(INTERVAL '1' DAY) AS ARRAY<STRING>), \
             CAST(named_struct('i', INTERVAL '1' DAY, 'j', 1) AS STRUCT<i: STRING, j: STRING>)"
        )?,
        ["[INTERVAL '1' DAY]|{INTERVAL '1' DAY, 1}"]
    );
    Ok(())
}

#[test]
fn a_nested_cast_renders_only_the_intervals_going_to_strings() -> R {
    let session = Session::new()?;
    assert_eq!(
        rows(
            &session,
            "SELECT CAST(CAST(named_struct('a', INTERVAL '1' DAY, 'b', INTERVAL '25' HOUR) \
               AS STRUCT<a: STRING, b: INTERVAL DAY>) AS STRING), \
             CAST(CAST(array(named_struct('a', INTERVAL '13' MONTH, 'b', INTERVAL '13' MONTH)) \
               AS ARRAY<STRUCT<a: STRING, b: INTERVAL YEAR>>) AS STRING)"
        )?,
        ["{INTERVAL '1' DAY, INTERVAL '1' DAY}|[{INTERVAL '13' MONTH, INTERVAL '1' YEAR}]"]
    );
    Ok(())
}

#[test]
fn a_lambda_variable_keeps_its_interval_fields() -> R {
    let session = Session::new()?;
    assert_eq!(
        rows(
            &session,
            "SELECT transform(array(INTERVAL '1' DAY), x -> CAST(x AS STRING)), \
             transform(array(INTERVAL '13' MONTH), x -> CAST(x AS STRING)), \
             transform(array(array(INTERVAL '1' DAY)), x -> CAST(x AS ARRAY<STRING>)), \
             transform(array(INTERVAL '1' DAY), x -> concat(x, 'a')), \
             transform(array(named_struct('a', INTERVAL '1' DAY)), x -> to_json(x))"
        )?,
        [
            "[INTERVAL '1' DAY]|[INTERVAL '13' MONTH]|[[INTERVAL '1' DAY]]|[INTERVAL '1' DAYa]|[{\"a\":\"INTERVAL '1' DAY\"}]"
        ]
    );
    Ok(())
}

#[test]
fn legacy_interval_differences_are_refused_by_name() -> R {
    let session = Session::new()?;
    block_on(session.sql("SET spark.sql.legacy.interval.enabled = true"))?;
    for expr in [
        "DATE '2024-02-01' - DATE '2024-01-01'",
        "TIMESTAMP '2024-02-01' - TIMESTAMP '2024-01-01'",
        "try_subtract(DATE '2024-02-01', DATE '2024-01-01')",
    ] {
        assert_eq!(
            answer(&session, expr).error_class.as_deref(),
            Some("KRISHIV_UNSUPPORTED_FEATURE"),
            "{expr}"
        );
    }
    Ok(())
}

#[test]
fn internal_interval_builtins_are_not_routines() -> R {
    let session = Session::new()?;
    for expr in [
        "tryeval(1)",
        "subtract_dates(DATE '2024-01-01', DATE '2024-01-01')",
    ] {
        assert_eq!(
            answer(&session, expr).error_class.as_deref(),
            Some("UNRESOLVED_ROUTINE"),
            "{expr}"
        );
    }
    Ok(())
}

#[test]
fn a_string_where_date_arithmetic_takes_days_reads_as_a_double() -> R {
    let session = Session::new()?;
    block_on(session.sql("SET spark.sql.ansi.enabled = false"))?;
    for expr in ["date'2020-01-30' - '1'", "date'2020-01-30' + '1'"] {
        let e = block_on(session.sql(&format!("SELECT {expr}")))
            .err()
            .ok_or("it resolved")?;
        let text = e.to_string();
        assert!(text.contains("\"1\" has the type \"DOUBLE\""), "{text}");
    }
    Ok(())
}

#[test]
fn wall_clock_casts_read_the_session_zone() -> R {
    let session = Session::new()?;
    block_on(session.sql("SET spark.sql.session.timeZone = America/Los_Angeles"))?;
    assert_eq!(
        rows(
            &session,
            "SELECT CAST(CAST(TIMESTAMP_NTZ'2024-03-11 00:00:00' AS TIMESTAMP) AS TIMESTAMP_NTZ), \
             CAST(TIMESTAMP_NTZ'2024-03-11 00:00:00' AS TIMESTAMP)"
        )?,
        ["2024-03-11 00:00:00|2024-03-11 00:00:00"]
    );
    Ok(())
}
